package com.bank.stream.model;

import java.util.LinkedHashMap;
import java.util.Map;

// A simulated checkpoint: committed offset, state, and the state schema id.
public class Checkpoint {
    private final long committedOffset;
    private final Map<String, Long> state;
    private final String stateSchema;   // e.g. "groupBy:accountId"

    public Checkpoint(long committedOffset, Map<String, Long> state, String stateSchema) {
        this.committedOffset = committedOffset;
        this.state = new LinkedHashMap<>(state);
        this.stateSchema = stateSchema;
    }

    public long getCommittedOffset() { return committedOffset; }
    public Map<String, Long> getState() { return new LinkedHashMap<>(state); }
    public String getStateSchema() { return stateSchema; }
}
