package com.bank.stream.service;

import com.bank.stream.model.Checkpoint;
import java.util.logging.Logger;

// Simulates saving, recovering, and compatibility-checking a checkpoint.
public class CheckpointManager {

    private static final Logger log = Logger.getLogger(CheckpointManager.class.getName());
    private Checkpoint saved;   // stands in for reliable storage (HDFS/S3)

    public void save(Checkpoint cp) {
        this.saved = cp;
        log.info(() -> "Checkpoint saved: offset=" + cp.getCommittedOffset()
                + " state=" + cp.getState() + " schema=" + cp.getStateSchema());
    }

    public Checkpoint recover() {
        if (saved == null) throw new IllegalStateException("no checkpoint to recover");
        log.info(() -> "Recovered from offset " + saved.getCommittedOffset()
                + " with state " + saved.getState());
        return saved;
    }

    // Restarting with a new query: compatible only if the state schema is unchanged.
    public boolean isCompatible(String newStateSchema) {
        if (saved == null) return true; // fresh start
        boolean ok = saved.getStateSchema().equals(newStateSchema);
        if (!ok) {
            log.severe(() -> "Incompatible restart: checkpoint schema '" + saved.getStateSchema()
                    + "' != new schema '" + newStateSchema + "' — use a fresh checkpoint");
        }
        return ok;
    }
}
