package com.bank.stream;

import com.bank.stream.model.Checkpoint;
import com.bank.stream.service.CheckpointManager;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: recover after a crash; reject an incompatible change.
public class CheckpointDemo {

    private static final Logger log = Logger.getLogger(CheckpointDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CheckpointManager cm = new CheckpointManager();

        // Batch 5 committed: running per-account counts saved to the checkpoint.
        cm.save(new Checkpoint(5, Map.of("SAV2001", 12L, "CUR3001", 7L), "groupBy:accountId"));

        // Simulated crash and restart with the SAME query → recover.
        log.info("--- simulated crash, restarting same query ---");
        Checkpoint recovered = cm.recover();
        log.info(() -> "Resuming after offset " + recovered.getCommittedOffset()
                + " (no reprocessing of committed batches, state intact)");

        // Safe change: same stateful schema, only trigger interval changed.
        boolean safe = cm.isCompatible("groupBy:accountId");
        log.info(() -> "Restart with trigger-only change compatible? " + safe);

        // Breaking change: group by a different key → incompatible.
        boolean breaking = cm.isCompatible("groupBy:branchCode");
        log.info(() -> "Restart with new grouping key compatible? " + breaking
                + " → must use a fresh checkpoint");

        log.info("Checkpoint demo complete.");
    }
}
